#![forbid(unsafe_code)]

use lc631_receipt_kernel::{
    ReceiptClass, ReceiptPolicy, ReceiptScope, ReceiptVerifier, ReplayGuard, SubjectRevision,
    UntrustedReceipt,
};

// Fixed legacy HMAC vector, not generated by the implementation under test.
const FIXTURE: &str = concat!(
    r#"{"claims":{"schema_version":"lc631-authenticated-receipt.v1","issuer":"legacy-fixture","class":"host_seed","subject_revision":"sha256:subject","scope":"host/user-span","nonce_hex":"000102030405060708090a0b0c0d0e0f","payload_digest":"sha256:"#,
    "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",
    r#"","issued_at_epoch":10,"expires_at_epoch":20,"parent_receipt_digest":null},"mac_sha256":"sha256:e021688fd12425959b0f1dd04abdfe0ae392f7c6ef90dd739589b4276a819d65"}"#
);

const OVERSIZED_BYTES: usize = 1_048_576;

fn oversized_json(pointer: &str) -> String {
    let mut value: serde_json::Value = serde_json::from_str(FIXTURE).unwrap();
    *value.pointer_mut(pointer).unwrap() = "x".repeat(OVERSIZED_BYTES).into();
    serde_json::to_string(&value).unwrap()
}

fn assert_decode_rejects_oversized(pointer: &str) {
    let input = oversized_json(pointer);
    // This is the actual public receipt decoder, not a source-text assertion or
    // a call to the opt-in size checker. Acceptance here leaves the oversized
    // object available to downstream Clone/receipt_digest consumers.
    assert!(
        serde_json::from_str::<UntrustedReceipt>(&input).is_err(),
        "public receipt decoding accepted {OVERSIZED_BYTES} bytes at {pointer}"
    );
}

#[test]
fn tlcx05_receipt_ingress_rejects_oversized_schema() {
    assert_decode_rejects_oversized("/claims/schema_version");
}

#[test]
fn tlcx05_receipt_ingress_rejects_oversized_nonce() {
    assert_decode_rejects_oversized("/claims/nonce_hex");
}

#[test]
fn tlcx05_receipt_ingress_rejects_oversized_payload_digest() {
    assert_decode_rejects_oversized("/claims/payload_digest");
}

#[test]
fn tlcx05_receipt_ingress_rejects_oversized_parent_digest() {
    assert_decode_rejects_oversized("/claims/parent_receipt_digest");
}

#[test]
fn tlcx05_receipt_ingress_rejects_oversized_mac() {
    assert_decode_rejects_oversized("/mac_sha256");
}

#[test]
fn tlcx05_receipt_ingress_from_value_also_rejects_oversized_parent() {
    let input = oversized_json("/claims/parent_receipt_digest");
    let value: serde_json::Value = serde_json::from_str(&input).unwrap();
    assert!(
        serde_json::from_value::<UntrustedReceipt>(value).is_err(),
        "already-owned JSON must not bypass receipt field limits"
    );
}

#[test]
fn tlcx05_receipt_ingress_preserves_legacy_mac_and_replay() {
    let wire: UntrustedReceipt = serde_json::from_str(FIXTURE).unwrap();
    wire.check_size_bounds().unwrap();
    assert_eq!(
        wire.receipt_digest(),
        "sha256:8d2ad1400cf65fdf6481476f2851c628feec426291cc55a923b75bf931bbbeed"
    );
    let verifier =
        ReceiptVerifier::from_key_bytes("legacy-fixture", &(0..32).collect::<Vec<u8>>()).unwrap();
    let policy = ReceiptPolicy::exact(
        ReceiptClass::HostSeed,
        SubjectRevision::checked("sha256:subject").unwrap(),
        ReceiptScope::checked("host/user-span").unwrap(),
        format!("sha256:{}", "a".repeat(64)),
        15,
    );
    let mut replay = ReplayGuard::default();
    verifier.verify(wire, &policy, &mut replay).unwrap();
    assert_eq!(replay.observed_count(), 1);
}
